(()=>{let register=false,setup=false;const $=id=>document.getElementById(id);function view(){register=setup||register;$('title').textContent=setup?'Create the administrator account':register?'Create an account':'Sign in';$('intro').textContent=setup?'This is the first account. It will manage questions, feedback and backups.':'Your notes and collections stay with your account.';$('name-label').hidden=!register;$('name').required=register;$('password-help').hidden=!register;$('password').minLength=register?12:0;$('password').autocomplete=register?'new-password':'current-password';$('submit-login').textContent=register?'Create account':'Sign in';$('switch-mode').hidden=setup;$('switch-mode').textContent=register?'Already have an account? Sign in':'Create an account';$('message').textContent=''}fetch('/api/account').then(r=>r.json()).then(x=>{if(x.user){location.href=x.user.role==='admin'?'/admin-home.html':'/sets.html';return}setup=x.setup;view()}).catch(()=>$('message').textContent='Could not connect to the question bank.');$('switch-mode').onclick=()=>{register=!register;view()};$('login-form').onsubmit=async e=>{e.preventDefault();$('submit-login').disabled=true;try{const r=await fetch(register?'/api/register':'/api/login',{method:'POST',headers:{'Content-Type':'application/json','X-Quiz-Admin':'1'},body:JSON.stringify({username:$('username').value,name:$('name').value,password:$('password').value})});const x=await r.json();if(!r.ok)throw Error(x.error);$('password').value='';const identity=await fetch('/api/account').then(r=>r.json());location.href=identity.user?.role==='admin'?'/admin-home.html':'/sets.html'}catch(err){$('message').textContent=err.message}finally{$('submit-login').disabled=false}}})();
